bag-black.png\",\"colorName\":\"Deep Slate Black\"},{\"id\":\"v4\",\"hex\":\"#008D1E\",\"image\":\"/images/bag-green.png\",\"colorName\":\"Deep Forest Green\"},{\"id\":\"v5\",\"hex\":\"#2563eb\",\"image\":\"/images/bag-blue.png\",\"colorName\":\"Cobalt Blue\"},{\"id\":\"v6\",\"hex\":\"#ea580c\",\"image\":\"/images/bag-orange.png\",\"colorName\":\"Bio Amber Orange\"},{\"id\":\"v-1792491807074\",\"hex\":\"#86C59E\",\"image\":\"/uploads/Untitleddesign2-1792491870868-z928z.png\",\"colorName\":\"New Custom Colorway\"},{\"id\":\"v-1792491852754\",\"hex\":\"#86C59E\",\"image\":\"/images/bag-green.png\",\"colorName\":\"New Custom Colorway\"}]},\"logoConfig\":{\"subtitle\":\"Sustainable Packaging\",\"badgeText\":\"INC.\",\"faviconUrl\":\"/uploads/ECOTEXINCONESTOPSOLUTIONFORYOU-1791449280633-grcds.png\",\"customLogoUrl\":\"/uploads/ECOTEXINCONESTOPSOLUTIONFORYOU-1791449274325-qdmrz.png\",\"wordmarkPrefix\":\"ECO\",\"wordmarkSuffix\":\"TEX\"},\"shopConfig\":{\"showHeroBanner\":true,\"heroBannerBadge\":\"LIMITED TIME ONLY\",\"heroBannerTitle\":\"Shop More,\\nSave More.\",\"heroBannerSubtitle\":\"Discover amazing deals on your favorite sustainable products & eco-friendly essentials.\",\"heroBannerBtnText\":\"EXPLORE COLLECTION\",\"heroBannerImage\":\"/uploads/Gemini_Generated_Image_afbs1pa-1793705274029-xaa4t.jpg\",\"heroBannerDiscountBadge\":\"UP TO 50\% OFF\",\"valueProp1Title\":\"Best Prices\",\"valueProp1Subtitle\":\"Guaranteed\",\"valueProp2Title\":\"Secure\",\"valueProp2Subtitle\":\"Payments\",\"valueProp3Title\":\"Fast Delivery\",\"valueProp3Subtitle\":\"Worldwide\",\"trustBar1Title\":\"Free Shipping\",\"trustBar1Subtitle\":\"On orders over $75\",\"trustBar2Title\":\"Easy Returns\",\"trustBar2Subtitle\":\"30-day returns\",\"trustBar3Title\":\"Premium Quality\",\"trustBar3Subtitle\":\"100\% original products\",\"trustBar4Title\":\"24/7 Support\",\"trustBar4Subtitle\":\"We\'re here to help\",\"catalogTitle\":\"Wholesale Catalog & Mill Collections\",\"testimonials\":[{\"id\":\"rev1\",\"role\":\"VP Supply Chain\",\"quote\":\"Switching our 42 regional grocery locations to Ecotex loop bags cut packaging overhead by 28\% while exceeding state single-use mandates.\",\"author\":\"Elena Vasquez\",\"avatar\":\"https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&w=200&q=80\",\"rating\":5,\"company\":\"SunWest Markets California\"},{\"id\":\"rev2\",\"role\":\"Creative Director\",\"quote\":\"The custom gold flexo printing on their black matte totes gave our boutique clients an unmistakable luxury feel that shoppers reuse every single day.\",\"author\":\"Marcus Vance\",\"avatar\":\"https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&w=200&q=80\",\"rating\":5,\"company\":\"Artisan Living Brands NY\"},{\"id\":\"rev3\",\"role\":\"Head of Procurement\",\"quote\":\"Flawless batch consistency across 150,000 custom printed units. Not a single torn handle during holiday freight distribution. Exceptional manufacturer.\",\"author\":\"Sarah Lindqvist\",\"avatar\":\"https://images.unsplash.com/photo-1573496359142-b8d87734a5a2?auto=format&fit=crop&w=200&q=80\",\"rating\":5,\"company\":\"Nordic Lifestyle Group\"},{\"id\":\"rev4\",\"role\":\"Global Logistics Director\",\"quote\":\"The heat-sealed seams hold up to 35 lbs without tearing. Their compostable PLA bags passed all our environmental compliance audits effortlessly.\",\"author\":\"David Chen\",\"avatar\":\"https://images.unsplash.com/photo-1500648767791-00dcc994a43e?auto=format&fit=crop&w=200&q=80\",\"rating\":5,\"company\":\"EcoWare Seattle\"},{\"id\":\"rev5\",\"role\":\"Operations Lead\",\"quote\":\"From artwork proofs to ocean freight delivery in 18 days flat. Ecotex\'s turnaround speed and volume wholesale pricing are unmatched in the US market.\",\"author\":\"Amara Okafor\",\"avatar\":\"https://images.unsplash.com/photo-1580489944761-15a19d654956?auto=format&fit=crop&w=200&q=80\",\"rating\":5,\"company\":\"BioRetail International\"},{\"id\":\"rev6\",\"role\":\"VP Merchandising\",\"quote\":\"Our retail stores have eliminated single-use bags entirely. Our shoppers love the durable aesthetic and often return just to buy extra totes.\",\"author\":\"Julian Reynolds\",\"avatar\":\"https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?auto=format&fit=crop&w=200&q=80\",\"rating\":5,\"company\":\"Pacific Organic Grocers\"}],\"galleryImages\":[{\"url\":\"https://images.unsplash.com/photo-1581092160607-ee22621dd758?auto=format&fit=crop&w=600&q=80\",\"caption\":\"High-Speed Automated Ultrasonic Welder\"},{\"url\":\"https://images.unsplash.com/photo-1581092335397-9583fe92d232?auto=format&fit=crop&w=600&q=80\",\"caption\":\"Virgin Non-Woven Polypropylene Rolls\"},{\"url\":\"https://images.unsplash.com/photo-1504384308090-c894fdcc538d?auto=format&fit=crop&w=600&q=80\",\"caption\":\"Cleanroom ISO Quality Testing\"},{\"url\":\"https://images.unsplash.com/photo-1586528116311-ad8dd3c8310d?auto=format&fit=crop&w=600&q=80\",\"caption\":\"Palletized Container Shipments\"},{\"url\":\"https://images.unsplash.com/photo-1580983218765-f663bec07b37?auto=format&fit=crop&w=600&q=80\",\"caption\":\"Precision Handle Box-Stitch Detail\"},{\"url\":\"https://images.unsplash.com/photo-1586864387967-d02ef85d93e8?auto=format&fit=crop&w=600&q=80\",\"caption\":\"Export-Grade Custom Cartons\"}],\"catalogSubtitle\":\"Explore our full manufacturing catalog of certified eco-friendly industrial & retail packaging with wholesale pricing tiers.\"},\"siteImages\":{\"heroBag\":\"/images/bag-black.png\",\"facilityPhoto\":\"/uploads/ecotextwebsiteimages-1793430074803-1gp0u.png\",\"shopBanner\":\"/images/bag-green.png\",\"aboutHero\":\"/images/versatility-banner-bg.jpg\"},\"aboutConfig\":{\"heroTitle\":\"About Us\",\"heroBgImage\":\"https://images.unsplash.com/photo-1556761175-5973dc0f32e7?auto=format&fit=crop&w=2000&q=85\",\"teamMembers\":[{\"id\":\"tm1\",\"bio\":\"Pioneered circular non-woven manufacturing across North America and South Asia with over two decades in sustainable polymer engineering.\",\"name\":\"Rashid Mahmood\",\"role\":\"Managing Director & Founder\",\"email\":\"rashid@ecotexinc.com\",\"image\":\"/uploads/zohair-1793431128020-almvg.webp\",\"linkedin\":\"#\"},{\"id\":\"tm2\",\"bio\":\"Leads our ASTM D6400 biodegradable testing laboratories and Global Recycled Standard (GRS) chain-of-custody compliance.\",\"name\":\"Farah Al-Sayed\",\"role\":\"Head of Quality & Materials Engineering\",\"email\":\"farah@ecotexinc.com\",\"image\":\"/uploads/hassan-1793431137185-1elzc.webp\",\"linkedin\":\"#\"},{\"id\":\"tm3\",\"bio\":\"Oversees enterprise carbon reduction accounting and California SB 270 / SB 54 regulatory packaging compliance.\",\"name\":\"Marcus Vance\",\"role\":\"Chief Sustainability Officer\",\"email\":\"marcus@ecotexinc.com\",\"image\":\"/uploads/ghazi-1793431145992-g8bqr.webp\",\"linkedin\":\"#\"},{\"id\":\"tm-1793431151834-tww1\",\"name\":\"New Executive Member\",\"role\":\"Director of Packaging Solutions\",\"bio\":\"Leading sustainable packaging engineering and client supply chain sustainability.\",\"image\":\"/uploads/mohibbahi-1793431185684-rupb0.webp\",\"email\":\"bhfbyuhfbhsd@gmail.com\",\"linkedin\":\"https://linkedin.com\",\"twitter\":\"\"}],\"founderImage\":\"/uploads/dayan-1793430087526-km8h2.webp\",\"heroSubtitle\":\"A sustainable future for packaging. Engineered with purpose, manufactured for impact.\",\"missionQuote\":\"We engineered our circular manufacturing framework around a simple premise: commercial packaging can protect goods and elevate brands without ever polluting our natural world.\",\"workshopImage\":\"/uploads/WhatsAppImage2026-08-13at43718-1793430094725-kh8tn.jpg\",\"storyParagraph1\":\"Founded to combat the global crisis of single-use plastic waste, Ecotex Inc. operates as a vertically integrated packaging manufacturer. We specialize in high-tensile reusable non-woven polypropylene totes, certified compostable cornstarch blends, and reclaimed post-industrial cotton wiping textiles.\",\"storyParagraph2\":\"From our corporate headquarters in California to state-of-the-art automated manufacturing facilities, every product is subjected to rigorous tensile testing, automated ultrasonic seam welding, and non-toxic water-based printing. We empower grocery retailers, boutique lifestyle brands, and logistics operations across the globe to achieve zero-waste compliance with full chain-of-custody audit trails.\",\"whyChooseUsTitle\":\"Why Choose Us\",\"whyChooseUsFeatures\":[{\"title\":\"100\% Recyclable Fabrics\",\"description\":\"Manufactured with virgin and pre-consumer polypropylene, lab-certified for 125+ reuse cycles.\"},{\"title\":\"Easy to Customize\",\"description\":\"Flexible sizing, ultrasonic handle sealing, custom gusset depths, and pantone-matched dyed fabrics.\"},{\"title\":\"24/7 B2B Global Support\",\"description\":\"Dedicated enterprise account directors for national retail chains, grocers, and FMCG brands.\"},{\"title\":\"Free Sample Verification\",\"description\":\"Physical pre-production specimen kits dispatched within 48 hours for tensile testing and color sign-off.\"},{\"title\":\"High-Definition Flexo Print\",\"description\":\"Zero-VOC soy and water-based ink flexography delivering photo-sharp photographic brand imprints.\"},{\"title\":\"Rapid Turnaround Times\",\"description\":\"Immediate dispatch for unbranded warehouse inventory and accelerated 10-14 day custom printed delivery.\"}],\"whyChooseUsSubtitle\":\"We combine German ultrasonic welding machinery, ISO 9001 certified batch audits, and non-toxic soy formulations to deliver high-capacity packaging engineered to outlast disposable plastic.\"},\"companyName\":\"Ecotex Inc.\",\"aboutMission\":\"We engineered our circular manufacturing framework around a simple premise: commercial packaging can protect goods and elevate brands without ever polluting our natural world.\",\"announcement\":\"🌱 Certified Recycled & Compostable Wholesale Packaging · Direct from Corona, CA Facility\",\"footerConfig\":{\"tagline\":\"Direct manufacturer of certified circular non-woven, compostable bio-PLA, and insulated wholesale packaging for global commercial enterprise.\",\"copyrightNotice\":\"Copyright 2026 © Ecotex Inc. All rights reserved.\",\"newsletterTitle\":\"Subscribe To Our Quarterly Newsletter\",\"newsletterBgImage\":\"https://images.unsplash.com/photo-1542744094-3a31f272c490?auto=format&fit=crop&w=1600&q=80\",\"newsletterSubtitle\":\"Receive direct mill pricing updates, material innovation whitepapers, and California SB 54 regulatory packaging briefs.\",\"socialLinks\":[{\"id\":\"soc-1\",\"name\":\"TikTok\",\"url\":\"https://linkedin.com\"},{\"id\":\"soc-3\",\"name\":\"Facebook\",\"url\":\"https://facebook.com\"},{\"id\":\"soc-4\",\"name\":\"Instagram\",\"url\":\"https://instagram.com\"},{\"id\":\"soc-1793773894733\",\"name\":\"LinkedIn\",\"url\":\"https://linkedin.com/company/\"}]},\"heroSubtitle\":\"memememmememe\",\"navbarConfig\":{\"phoneDisplay\":\"(951) 555-ECOTEX\",\"ctaButtonText\":\"START SH\",\"announcementText\":\"🌱 Certified Recycled & Compostable Wholesale Packaging · Direct from Corona, CA Facility\",\"announcementActive\":true},\"plantAddress\":\"Sector 15, Korangi Industrial Area, Karachi, PK\",\"supportEmail\":\"orders@ecotexinc.com\",\"contactConfig\":{\"email\":\"orders@ecotexinc.com\",\"phone\":\"+1 (951) 450-9773\",\"headline\":\"Let’s Engineer Your Sustainable Wholesale Packaging Solution\",\"twitterUrl\":\"https://twitter.com\",\"facebookUrl\":\"https://facebook.com\",\"linkedinUrl\":\"https://linkedin.com\",\"instagramUrl\":\"https://instagram.com\",\"plantAddress\":\"Sector 15, Korangi Industrial Area, Karachi, PK\",\"googleMapsUrl\":\"https://maps.google.com/?q=1200+Industrial+Parkway,+Corona,+CA+92881\",\"secondaryPhone\":\"+1 (951) 450-9773\",\"facilityAddress\":\"1200 Industrial Parkway, Corona, CA 92881\",\"googleMapsEmbedUrl\":\"https://maps.google.com/maps?q=1200\%20Industrial\%20Parkway\%2C\