stBadges\":[\"Fast Turnaround Times\",\"A friendly, open and honest service\",\"Ethical and Fairly Traded Products\",\"Expert Customer Service\"],\"sustainableFashionTitle\":\"Sustainable Fashion For A Greener Tomorrow\",\"sustainableFashionSubtitle\":\"Discover our eco-friendly bags made from sustainable materials. Join the movement to reduce environmental impact without compromising style!\"},\"announcementActive\":true,\"notificationConfig\":{\"smtpHost\":\"\",\"smtpPass\":\"\",\"smtpPort\":587,\"smtpUser\":\"\",\"adminEmail\":\"orders@ecotexinc.com\",\"emailEnabled\":true,\"whatsappNumber\":\"\",\"whatsappEnabled\":true,\"emailSubjectTemplate\":\"🛒 New Order {{orderId}} — {{customerName}} ({{total}})\",\"whatsappMessageTemplate\":\"📦 *New Order Received!*\\n\\n*Order ID:* {{orderId}}\\n*Customer:* {{customerName}}\\n*Company:* {{companyName}}\\n*Total:* {{total}}\\n*Items:* {{itemsSummary}}\\n\\nPlease log in to the Ecotex admin panel to review and process this order.\"},\"orderNotifications\":{\"emailEnabled\":false,\"whatsappNumber\":\"+92 332 8784015\",\"whatsappEnabled\":true,\"autoOpenWhatsapp\":true,\"whatsappGreeting\":\"New Wholesale Order Received on EcoTex Storefront\",\"notificationEmail\":\"orders@ecotexinc.com\"},\"sustainabilityConfig\":{\"metrics\":{\"reusableTrips\":\"125+\",\"carbonReduction\":\"-84\%\",\"plasticDisplaced\":\"50M+\",\"recyclablePercent\":\"100\%\"},\"circularSteps\":[{\"desc\":\"Utilizing certified post-industrial virgin PP regrind, non-GMO corn-derived PLA resins, and reclaimed apparel cut-offs.\",\"step\":\"01\",\"title\":\"Responsible Material Sourcing\"},{\"desc\":\"Sonic molecular excitation bonds fabric panels with unbreakable tensile strength without toxic glues or volatile emissions.\",\"step\":\"02\",\"title\":\"Ultrasonic Zero-Solvent Welding\"},{\"desc\":\"Engineered to withstand 125+ heavy shopping cycles, each tote displaces hundreds of single-use polybags from city landfills.\",\"step\":\"03\",\"title\":\"Extended Multi-Year Lifecycle\"},{\"desc\":\"100\% pelletized back into polymer pellets at end-of-life, while our bio line returns to soil biomass within 90-180 days.\",\"step\":\"04\",\"title\":\"Pure Mechanical & Biological Recovery\"}]},\"facilitiesConfig\":{\"title\":\"State-of-the-Art Manufacturing & Fulfillment Facilities\",\"subtitle\":\"Dual-continental operations combining California wholesale fulfillment with high-speed automated manufacturing mills.\",\"storySnippet\":\"From automated ultrasonic welding to high-definition 8-color flexographic printing, our facilities are engineered for maximum circularity and zero-landfill compliance.\",\"annualCapacity\":\"50,000,000+ Units / Year\",\"certificationsMetric\":\"ISO 9001:2015 & ASTM D6400\",\"activeLinesMetric\":\"14 High-Speed Extrusion Lines\",\"showOnHomepage\":true,\"bannerImage\":\"https://images.unsplash.com/photo-1581091226825-a6a2a5aee158?auto=format&fit=crop&w=1400&q=85\",\"hubs\":[{\"name\":\"Corona Distribution & Testing Hub\",\"tag\":\"US Headquarters & Fulfillment\",\"address\":\"1200 Industrial Parkway, Corona, CA 92881\",\"capabilities\":[\"Same-Day Pallet Dispatch\",\"ASTM Tensile Testing Lab\",\"Custom Sample Prototyping\"],\"image\":\"/uploads/70-1793430113598-w5yry.png\",\"googleMapsUrl\":\"https://maps.google.com/?q=1200+Industrial+Parkway,+Corona,+CA+92881\"},{\"name\":\"Primary Manufacturing Plant\",\"tag\":\"Heavy Industrial Production\",\"address\":\"Sector 15, Korangi Industrial Area, Karachi, PK\",\"capabilities\":[\"Automated Ultrasonic Welding\",\"8-Color Flexographic Printing\",\"Virgin PP & Bio-PLA Extrusion\"],\"image\":\"/uploads/WhatsAppImage2026-07-25at12495-1793430119368-2st5d.webp\",\"googleMapsUrl\":\"https://maps.google.com/?q=Korangi+Industrial+Area+Karachi\"}]},\"shippingConfig\":{\"freeShippingThreshold\":1000,\"standardShippingRate\":50,\"expressShippingRate\":120,\"estimatedTransitDays\":\"3-5 Business Days (Continental US)\",\"freightCarrier\":\"Direct LTL Pallet Freight (FedEx Freight / R+L Carriers / Old Dominion)\",\"shippingPolicyNotice\":\"All wholesale pallet orders ship FOB Corona, CA warehouse. Shrink-wrapped with corner guards on 40x48 heat-treated pallets.\",\"warehouseHub\":\"Corona Distribution & Fulfillment Center, 1200 Industrial Parkway, Corona, CA 92881\",\"localPickupAvailable\":true,\"sampleDispatchNotice\":\"Free fabric swatches & physical sample bags dispatched within 24 hours via USPS Priority Mail.\"},\"currencySymbol\":\"$\",\"currencyCode\":\"USD\",\"taxRatePercent\":0,\"taxExemptionNotice\":\"Valid California resale certificate required at checkout for wholesale sales tax exemption.\",\"guaranteeNotice\":\"100\% Quality & Defect Replacement Guarantee within 30 days of shipment receipt.\",\"sampleKitPolicy\":\"Complimentary fabric swatch ring and sample bags available for enterprise retail procurement.\",\"version\":11,\"heroBackgroundImage\":\"/uploads/2-removebg-preview-1793429998607-r8g8y.png\"}', NOW())
